+/** Theoretical (from sales) versus actual (consume movements) use per item between two days, inclusive. */
+export function varianceReport(store, from, to) {
+  const rows = new Map();
+  const row = (itemId) => {
+    if (!rows.has(itemId)) rows.set(itemId, { theoretical: 0, actual: 0 });
+    return rows.get(itemId);
+  };
+  for (const s of store.data.sales ?? []) {
+    const day = s.soldAt.slice(0, 10);
+    if (day < from || day > to) continue;
+    const dish = (store.data.dishes ?? []).find((d) => d.id === s.dishId);
+    if (!dish) continue;
+    for (const n of scaled(getRecipe(store, dish.recipeId), s.qty)) row(n.itemId).theoretical += n.qty;
+  }
+  for (const m of store.data.movements) {
+    if (m.type !== "consume") continue;
+    const day = m.at.slice(0, 10);
+    if (day < from || day > to) continue;
+    const batch = store.data.batches.find((b) => b.id === m.batchId);
+    if (batch) row(batch.itemId).actual += m.qty;
+  }
+  const r3 = (n) => Math.round(n * 1000) / 1000;
+  return [...rows]
+    .map(([itemId, v]) => ({
+      itemId,
+      name: store.data.items.find((i) => i.id === itemId)?.name ?? "",
+      theoretical: r3(v.theoretical),
+      actual: r3(v.actual),
+      difference: r3(v.actual - v.theoretical),
+    }))
+    .filter((l) => l.theoretical > 0 || l.actual > 0)
+    .sort((a, b) => a.itemId - b.itemId);
+}
